import{_ as e,o,c as t,a2 as c}from"./chunks/framework.C0KMm31j.js";const n="/Nav2ArticlesSite/article-assets/2026-07-14/myagv_nav2_cover.png",l="/Nav2ArticlesSite/article-assets/2026-07-14/myagv_01_launch_boundary.png",s="/Nav2ArticlesSite/article-assets/2026-07-14/myagv_02_custom_localization.png",i="/Nav2ArticlesSite/article-assets/2026-07-14/myagv_03_external_inputs.png",r="/Nav2ArticlesSite/article-assets/2026-07-14/myagv_04_planning_bt.png",d="/Nav2ArticlesSite/article-assets/2026-07-14/myagv_05_dwb_control.png",p="/Nav2ArticlesSite/article-assets/2026-07-14/myagv_06_uart_loop.png",k=JSON.parse('{"title":"没有 AMCL，Nav2 怎么跑？拆解 map→base_link 自研定位的实车全数据流","description":"第一篇文章从 myworldbringup/entry.launch.py 出发，分析了 Ignition、bridge、AMCL、TEB 和仿真底盘组成的完整闭环。但机器人真正上车后，系统边界完全不同：Gazebo 不再提供传感器和里程计，AMCL 也不再负责定位，所有关键状态都来自车上的真实系统","frontmatter":{"title":"没有 AMCL，Nav2 怎么跑？拆解 `map→base_link` 自研定位的实车全数据流","description":"第一篇文章从 myworldbringup/entry.launch.py 出发，分析了 Ignition、bridge、AMCL、TEB 和仿真底盘组成的完整闭环。但机器人真正上车后，系统边界完全不同：Gazebo 不再提供传感器和里程计，AMCL 也不再负责定位，所有关键状态都来自车上的真实系统","date":"2026-07-14","section":"一 · 架构与启动","readingTime":8,"source":"2026-07-14/myagv_entry_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-14/myagv_nav2_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/myagv-entry-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"没有 AMCL，Nav2 怎么跑？拆解 `map→base_link` 自研定位的实车全数据流"}],["meta",{"property":"og:description","content":"第一篇文章从 myworldbringup/entry.launch.py 出发，分析了 Ignition、bridge、AMCL、TEB 和仿真底盘组成的完整闭环。但机器人真正上车后，系统边界完全不同：Gazebo 不再提供传感器和里程计，AMCL 也不再负责定位，所有关键状态都来自车上的真实系统"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/myagv-entry-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-14/myagv_nav2_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-14"}],["meta",{"name":"twitter:title","content":"没有 AMCL，Nav2 怎么跑？拆解 `map→base_link` 自研定位的实车全数据流"}],["meta",{"name":"twitter:description","content":"第一篇文章从 myworldbringup/entry.launch.py 出发，分析了 Ignition、bridge、AMCL、TEB 和仿真底盘组成的完整闭环。但机器人真正上车后，系统边界完全不同：Gazebo 不再提供传感器和里程计，AMCL 也不再负责定位，所有关键状态都来自车上的真实系统"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-14/myagv_nav2_cover.png"}]],"prev":{"text":"机器人“自救”时，数据到底怎么流？拆解 Nav2 Behavior Server 全链路","link":"/nav2/behavior-server-full-dataflow"},"next":{"text":"一条 `/cmd_vel` 是怎样诞生的？从 `entry.launch.py` 拆解 Nav2 全数据流","link":"/nav2/myworld-bringup-entry-full-dataflow"}},"headers":[],"relativePath":"nav2/myagv-entry-full-dataflow.md","filePath":"nav2/myagv-entry-full-dataflow.md","lastUpdated":null}'),m={name:"nav2/myagv-entry-full-dataflow.md"};function h(_,a,b,u,v,g){return o(),t("div",null,[...a[0]||(a[0]=[c('<h1 id="没有-amcl-nav2-怎么跑-拆解-map→base-link-自研定位的实车全数据流" tabindex="-1">没有 AMCL，Nav2 怎么跑？拆解 <code>map→base_link</code> 自研定位的实车全数据流 <a class="header-anchor" href="#没有-amcl-nav2-怎么跑-拆解-map→base-link-自研定位的实车全数据流" aria-label="Permalink to &quot;没有 AMCL，Nav2 怎么跑？拆解 `map→base_link` 自研定位的实车全数据流&quot;">​</a></h1><p><img src="'+n+'" alt="myAGV Nav2 实车数据流封面"></p><p>第一篇文章从 <code>myworld_bringup/entry.launch.py</code> 出发，分析了 Ignition、bridge、AMCL、TEB 和仿真底盘组成的完整闭环。但机器人真正上车后，系统边界完全不同：Gazebo 不再提供传感器和里程计，AMCL 也不再负责定位，所有关键状态都来自车上的真实系统。</p><p><code>myagv_test_bringup/launch/entry.launch.py</code> 正是这个实车入口。它默认隐藏 Gazebo 和 AMCL 接口，由自研定位实时发布 <code>map→base_link</code>，真实 C200 雷达发布 LaserScan，Nav2 负责规划与控制，最后通过 <code>controlpub</code> 把 <code>/cmd_vel</code> 转换成底盘通信消息。</p><p>本文沿数据流方向拆解这套架构：外部系统需要提供什么，Nav2 内部如何消费，速度命令又如何走到串口与电机。</p><h2 id="一、实车入口真正启动了什么" tabindex="-1">一、实车入口真正启动了什么 <a class="header-anchor" href="#一、实车入口真正启动了什么" aria-label="Permalink to &quot;一、实车入口真正启动了什么&quot;">​</a></h2><p><code>entry.launch.py</code> 默认参数面向板端实车：<code>use_sim_time=False</code>、<code>use_simulator=False</code>、<code>autostart=true</code>。实际启动的核心组件只有五组：</p><h3 id="_1-1-rviz-子-launch" tabindex="-1">1.1 RViz 子 Launch <a class="header-anchor" href="#_1-1-rviz-子-launch" aria-label="Permalink to &quot;1.1 RViz 子 Launch&quot;">​</a></h3><p>由 <code>use_rviz</code> 控制，板端无图形界面时可以关闭。</p><h3 id="_1-2-map-server" tabindex="-1">1.2 <code>map_server</code> <a class="header-anchor" href="#_1-2-map-server" aria-label="Permalink to &quot;1.2 `map_server`&quot;">​</a></h3><p>读取 <code>maps/out.yaml</code> 和栅格地图，发布 <code>/map</code>。</p><h3 id="_1-3-lifecycle-manager-localization" tabindex="-1">1.3 <code>lifecycle_manager_localization</code> <a class="header-anchor" href="#_1-3-lifecycle-manager-localization" aria-label="Permalink to &quot;1.3 `lifecycle_manager_localization`&quot;">​</a></h3><p>名字虽然带 localization，但当前只管理 <code>map_server</code>，不管理 AMCL。</p><h3 id="_1-4-navigation-launch-py" tabindex="-1">1.4 <code>navigation_launch.py</code> <a class="header-anchor" href="#_1-4-navigation-launch-py" aria-label="Permalink to &quot;1.4 `navigation_launch.py`&quot;">​</a></h3><p>启动 planner、controller、smoother、behavior、bt_navigator、waypoint_follower、velocity_smoother 和生命周期管理器。</p><h3 id="_1-5-controlpub" tabindex="-1">1.5 <code>controlpub</code> <a class="header-anchor" href="#_1-5-controlpub" aria-label="Permalink to &quot;1.5 `controlpub`&quot;">​</a></h3><p>把 Nav2 的 <code>/cmd_vel</code> 转换为 <code>/control_to_uart</code>。</p><p><img src="'+l+'" alt="myAGV 实车入口启动边界"></p><p>Gazebo 服务端和客户端仍保留条件代码，但默认 <code>use_simulator=False</code>，不会创建进程。<code>locationpub</code>、<code>laserpub</code>、<code>map2base_tf</code>、静态 <code>odom→base_link</code>、robot_state_publisher 和 joint_state_publisher 都被注释，没有加入 LaunchDescription。</p><p>这意味着入口只负责 Nav2 和地图，不再伪造任何真实车辆状态。</p><h2 id="二、为什么可以不启动-amcl" tabindex="-1">二、为什么可以不启动 AMCL <a class="header-anchor" href="#二、为什么可以不启动-amcl" aria-label="Permalink to &quot;二、为什么可以不启动 AMCL&quot;">​</a></h2><p>Nav2 并不强制要求使用 AMCL。它真正要求的是：在传感器消息对应的时间点，TF Buffer 能查询机器人从全局坐标系到本体坐标系的位姿。</p><p>当前系统由自研定位直接发布动态：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map → base_link</span></span></code></pre></div><p><img src="'+s+'" alt="自研定位直接发布 map→base_link"></p><p>自研定位可以融合 GNSS、IMU、轮速、激光匹配或其他定位结果，但输出必须满足四项约束：</p><h3 id="_2-1-固定父子坐标系" tabindex="-1">2.1 固定父子坐标系 <a class="header-anchor" href="#_2-1-固定父子坐标系" aria-label="Permalink to &quot;2.1 固定父子坐标系&quot;">​</a></h3><p>父坐标系是 <code>map</code>，子坐标系是 <code>base_link</code>。</p><h3 id="_2-2-实时更新动态变换" tabindex="-1">2.2 实时更新动态变换 <a class="header-anchor" href="#_2-2-实时更新动态变换" aria-label="Permalink to &quot;2.2 实时更新动态变换&quot;">​</a></h3><p>变换必须实时更新，不能用一次性静态 TF 代替运动位姿。</p><h3 id="_2-3-统一时间基准" tabindex="-1">2.3 统一时间基准 <a class="header-anchor" href="#_2-3-统一时间基准" aria-label="Permalink to &quot;2.3 统一时间基准&quot;">​</a></h3><p>时间戳要与雷达、里程计和 Nav2 使用同一时间基准。当前实车默认使用系统时间，不是 <code>/clock</code>。</p><h3 id="_2-4-保持唯一权威发布者" tabindex="-1">2.4 保持唯一权威发布者 <a class="header-anchor" href="#_2-4-保持唯一权威发布者" aria-label="Permalink to &quot;2.4 保持唯一权威发布者&quot;">​</a></h3><p>只能有一个权威发布者。不能同时发布另一条 <code>map→base_link</code>，也不能再拼出一条与其竞争的 <code>map→odom→base_link</code>。</p><p>当前 local costmap 和 global costmap 的 <code>global_frame</code> 都配置为 <code>map</code>，<code>robot_base_frame</code> 都是 <code>base_link</code>。因此它们会直接查询 <code>map→base_link</code>，不依赖 AMCL 生成 <code>map→odom</code>。</p><h2 id="三、外部系统必须提供哪些数据" tabindex="-1">三、外部系统必须提供哪些数据 <a class="header-anchor" href="#三、外部系统必须提供哪些数据" aria-label="Permalink to &quot;三、外部系统必须提供哪些数据&quot;">​</a></h2><p>去掉仿真和 AMCL 后，Nav2 仍然需要地图、位姿、障碍物和速度反馈。</p><p><img src="'+i+`" alt="地图、雷达、TF 与里程计输入"></p><p>地图来自本包：<code>map_server</code> 读取 <code>maps/out.yaml</code>，以 transient local 方式发布 <code>/map</code>。新启动的 global costmap 可以立即收到最近一帧静态地图。</p><p>机器人位姿来自外部自研定位发布的 <code>map→base_link</code>。</p><p>真实 C200 雷达必须发布：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>topic: /c200_lidar_node1/scan</span></span>
<span class="line"><span>type:  sensor_msgs/msg/LaserScan</span></span></code></pre></div><p>LaserScan 的 <code>frame_id</code> 必须能通过 TF 连接到 <code>base_link</code>。由于入口没有启动 robot_state_publisher，如果雷达坐标系不是 <code>base_link</code>，外部驱动或专门 TF 节点还必须提供 <code>base_link→lidar_frame</code>。</p><p>底盘或状态融合系统还需要发布 <code>/odom</code>。它在当前架构中主要提供速度反馈：<code>bt_navigator</code> 和 <code>controller_server</code> 使用当前运动状态，<code>velocity_smoother</code> 虽然配置了 <code>odom_topic</code>，但当前 <code>feedback=OPEN_LOOP</code>，速度平滑主要依据上一周期命令估算。</p><h2 id="四、两张代价地图为何都使用-map" tabindex="-1">四、两张代价地图为何都使用 map <a class="header-anchor" href="#四、两张代价地图为何都使用-map" aria-label="Permalink to &quot;四、两张代价地图为何都使用 map&quot;">​</a></h2><p>global costmap 组合 StaticLayer、ObstacleLayer 和 InflationLayer。它使用 <code>/map</code> 建立全局环境，用 C200 LaserScan 标记和清除临时障碍，再扩张机器人安全半径。</p><p>local costmap 是 <code>3 m × 3 m</code> 的 rolling window，使用 VoxelLayer 和 InflationLayer，更新频率 <code>5 Hz</code>。虽然窗口会随机器人移动，但它的全局坐标系同样是 <code>map</code>，移动中心直接由 <code>map→base_link</code> 决定。</p><p>这种配置与标准的 <code>map→odom→base_link</code> 不同：它省掉 odom 坐标层，接口更直接；代价是定位输出的短时连续性会直接影响 local costmap 和 controller。如果 <code>map→base_link</code> 出现跳变，局部窗口和控制误差也会同步跳变。</p><p>因此自研定位不仅要“全局准确”，还要满足局部控制需要的连续、低延迟和高更新率。</p><h2 id="五、目标如何变成全局路径" tabindex="-1">五、目标如何变成全局路径 <a class="header-anchor" href="#五、目标如何变成全局路径" aria-label="Permalink to &quot;五、目标如何变成全局路径&quot;">​</a></h2><p>RViz 或上层调度系统发送 <code>NavigateToPose</code> 后，<code>bt_navigator</code> 接收目标并运行行为树。</p><p><img src="`+r+'" alt="行为树与 GridBasedAstar 全局规划"></p><p>行为树从 TF 获取当前 <code>base_link</code> 在 <code>map</code> 中的位姿，然后调用 <code>planner_server</code>。当前参数虽然加载了 Navfn、Smac 和 Theta* 等多个插件，但自定义 <code>selected_planner=GridBasedAstar</code> 固定选择 NavfnPlanner，并启用 A* 搜索。</p><p>planner 的核心输入是当前位姿、目标位姿和 global costmap，输出为 <code>map</code> 坐标系的 <code>nav_msgs/msg/Path</code>。路径可以经过 <code>SimpleSmoother</code> 平滑，再由 FollowPath Action 送入 controller。</p><p>规划或控制失败时，行为树可以调用 Spin、BackUp、DriveOnHeading、Wait 等行为，完成恢复后重新规划。所有这些节点都由 <code>lifecycle_manager_navigation</code> 统一配置和激活。</p><h2 id="六、dwb-如何生成局部速度" tabindex="-1">六、DWB 如何生成局部速度 <a class="header-anchor" href="#六、dwb-如何生成局部速度" aria-label="Permalink to &quot;六、DWB 如何生成局部速度&quot;">​</a></h2><p>与第一篇使用 TEB 不同，当前实车参数选择：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bt_navigator.selected_controller = DWB</span></span></code></pre></div><p>因此 <code>controller_server</code> 调用 <code>dwb_core::DWBLocalPlanner</code>。</p><p><img src="'+d+'" alt="DWB 局部控制数据流"></p><p>DWB 的输入包括全局 Path、<code>map→base_link</code> 当前位姿、<code>/odom</code> 当前速度和 local costmap 障碍物。每个控制周期可以概括为：</p><h3 id="_6-1-采样候选速度" tabindex="-1">6.1 采样候选速度 <a class="header-anchor" href="#_6-1-采样候选速度" aria-label="Permalink to &quot;6.1 采样候选速度&quot;">​</a></h3><p>在允许的线速度和角速度范围内采样候选速度。</p><h3 id="_6-2-模拟短时轨迹" tabindex="-1">6.2 模拟短时轨迹 <a class="header-anchor" href="#_6-2-模拟短时轨迹" aria-label="Permalink to &quot;6.2 模拟短时轨迹&quot;">​</a></h3><p>对每组速度向前模拟短时轨迹。</p><h3 id="_6-3-检查碰撞并评分" tabindex="-1">6.3 检查碰撞并评分 <a class="header-anchor" href="#_6-3-检查碰撞并评分" aria-label="Permalink to &quot;6.3 检查碰撞并评分&quot;">​</a></h3><p>检查轨迹是否碰撞，并由多个 Critic 评分。</p><h3 id="_6-4-综合-critic-代价" tabindex="-1">6.4 综合 Critic 代价 <a class="header-anchor" href="#_6-4-综合-critic-代价" aria-label="Permalink to &quot;6.4 综合 Critic 代价&quot;">​</a></h3><p>综合 PathAlign、PathDist、GoalAlign、GoalDist、BaseObstacle、Oscillation 和 RotateToGoal 等代价。</p><h3 id="_6-5-选择轨迹并输出-twist" tabindex="-1">6.5 选择轨迹并输出 Twist <a class="header-anchor" href="#_6-5-选择轨迹并输出-twist" aria-label="Permalink to &quot;6.5 选择轨迹并输出 Twist&quot;">​</a></h3><p>选择合法且总代价最低的轨迹，输出对应 Twist。</p><p><code>controller_server</code> 运行频率为 <code>20 Hz</code>，内部 <code>cmd_vel</code> 被 remap 为 <code>/cmd_vel_nav</code>，避免未经平滑的速度直接进入底盘。</p><h2 id="七、从-cmd-vel-到-control-to-uart" tabindex="-1">七、从 /cmd_vel 到 /control_to_uart <a class="header-anchor" href="#七、从-cmd-vel-到-control-to-uart" aria-label="Permalink to &quot;七、从 /cmd_vel 到 /control_to_uart&quot;">​</a></h2><p><code>velocity_smoother</code> 订阅 <code>/cmd_vel_nav</code>，按照最大速度、加速度、减速度和超时约束生成最终 <code>/cmd_vel</code>。当前平滑频率为 <code>20 Hz</code>，最大线速度 <code>0.26 m/s</code>，最大角速度 <code>1.0 rad/s</code>。</p><p><img src="'+p+`" alt="从 Nav2 速度到串口底盘闭环"></p><p><code>controlpub</code> 是 Nav2 与自研底盘协议之间的适配层。它订阅 <code>geometry_msgs/msg/Twist</code>，发布 <code>byd_custom_msgs/msg/ControlRes</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ControlRes.v          = Twist.linear.x</span></span>
<span class="line"><span>ControlRes.w          = Twist.angular.z</span></span>
<span class="line"><span>ControlRes.v_lift     = 0.0</span></span>
<span class="line"><span>ControlRes.w_rotation = 0.0</span></span></code></pre></div><p>输出 topic 为 <code>/control_to_uart</code>，后续串口或 CAN 节点把消息发送给底盘控制器。电机执行后，底盘产生新的 <code>/odom</code>，自研定位产生新的 <code>map→base_link</code>，真实雷达产生新的扫描，这些反馈再进入 Nav2 的下一控制周期。</p><p>完整实车闭环是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>导航目标</span></span>
<span class="line"><span>  → bt_navigator</span></span>
<span class="line"><span>  → GridBasedAstar 全局路径</span></span>
<span class="line"><span>  → DWB 局部速度</span></span>
<span class="line"><span>  → /cmd_vel_nav</span></span>
<span class="line"><span>  → velocity_smoother</span></span>
<span class="line"><span>  → /cmd_vel</span></span>
<span class="line"><span>  → controlpub</span></span>
<span class="line"><span>  → /control_to_uart</span></span>
<span class="line"><span>  → 串口/CAN与底盘</span></span>
<span class="line"><span>  → /odom + map→base_link + LaserScan</span></span>
<span class="line"><span>  → Nav2 下一周期</span></span></code></pre></div><h2 id="八、实车联调最容易忽略的检查项" tabindex="-1">八、实车联调最容易忽略的检查项 <a class="header-anchor" href="#八、实车联调最容易忽略的检查项" aria-label="Permalink to &quot;八、实车联调最容易忽略的检查项&quot;">​</a></h2><h3 id="_8-1-检查-use-sim-time-的运行期值" tabindex="-1">8.1 检查 <code>use_sim_time</code> 的运行期值 <a class="header-anchor" href="#_8-1-检查-use-sim-time-的运行期值" aria-label="Permalink to &quot;8.1 检查 \`use_sim_time\` 的运行期值&quot;">​</a></h3><p>虽然 YAML 中多个节点写着 True，但入口通过 <code>RewrittenYaml</code> 统一覆盖为 launch 参数；默认实车运行时最终值是 False。</p><h3 id="_8-2-检查-tf-唯一性" tabindex="-1">8.2 检查 TF 唯一性 <a class="header-anchor" href="#_8-2-检查-tf-唯一性" aria-label="Permalink to &quot;8.2 检查 TF 唯一性&quot;">​</a></h3><p><code>map→base_link</code> 必须只有一个发布者，入口中被停用的 <code>map2base_tf</code> 和静态 TF 不能重新启用。</p><h3 id="_8-3-检查雷达时间和坐标" tabindex="-1">8.3 检查雷达时间和坐标 <a class="header-anchor" href="#_8-3-检查雷达时间和坐标" aria-label="Permalink to &quot;8.3 检查雷达时间和坐标&quot;">​</a></h3><p>LaserScan 时间戳要与定位一致，<code>frame_id</code> 必须能连到 <code>base_link</code>，否则 costmap 会丢弃数据。</p><h3 id="_8-4-检查定位连续性" tabindex="-1">8.4 检查定位连续性 <a class="header-anchor" href="#_8-4-检查定位连续性" aria-label="Permalink to &quot;8.4 检查定位连续性&quot;">​</a></h3><p>全局位置正确但帧间跳变明显，依然会造成 local costmap 抖动、DWB 评分突变和速度不稳定。</p><h3 id="_8-5-检查控制接口链" tabindex="-1">8.5 检查控制接口链 <a class="header-anchor" href="#_8-5-检查控制接口链" aria-label="Permalink to &quot;8.5 检查控制接口链&quot;">​</a></h3><p>排查机器人不动时要依次检查以下接口，不能只看 controller 是否 active。</p><h4 id="_8-5-1-检查-cmd-vel-nav" tabindex="-1">8.5.1 检查 <code>/cmd_vel_nav</code> <a class="header-anchor" href="#_8-5-1-检查-cmd-vel-nav" aria-label="Permalink to &quot;8.5.1 检查 \`/cmd_vel_nav\`&quot;">​</a></h4><p>确认 Controller Server 是否输出未经平滑的导航速度。</p><h4 id="_8-5-2-检查-cmd-vel" tabindex="-1">8.5.2 检查 <code>/cmd_vel</code> <a class="header-anchor" href="#_8-5-2-检查-cmd-vel" aria-label="Permalink to &quot;8.5.2 检查 \`/cmd_vel\`&quot;">​</a></h4><p>确认 Velocity Smoother 是否输出最终速度。</p><h4 id="_8-5-3-检查-control-to-uart" tabindex="-1">8.5.3 检查 <code>/control_to_uart</code> <a class="header-anchor" href="#_8-5-3-检查-control-to-uart" aria-label="Permalink to &quot;8.5.3 检查 \`/control_to_uart\`&quot;">​</a></h4><p>确认 <code>controlpub</code> 是否完成底盘协议转换与发布。</p><h2 id="九、核心结论" tabindex="-1">九、核心结论 <a class="header-anchor" href="#九、核心结论" aria-label="Permalink to &quot;九、核心结论&quot;">​</a></h2><p>没有 AMCL 并不意味着没有定位链。当前架构把定位责任完整交给自研系统，并把接口压缩成一条动态 <code>map→base_link</code>。Nav2 不关心这条 TF 是由粒子滤波、组合导航还是地图匹配生成，只关心它是否实时、连续、唯一且与传感器时间一致。</p><p>与第一篇仿真链路相比，这套实车系统少了 Gazebo 和 bridge，多了三个真正的工程边界：自研定位 TF、真实 C200 雷达，以及 <code>/cmd_vel→ControlRes→串口底盘</code> 的协议适配。实车 Nav2 的稳定性，最终取决于这些边界是否被清晰定义并逐段验证。</p>`,100)])])}const f=e(m,[["render",h]]);export{k as __pageData,f as default};
